from itertools import count
import sys

def stack_size(size=2):
    """Get stack size for caller's frame."""
    try:
        frame = sys._getframe(size)
        for size in count(size):
            frame = frame.f_back
            if not frame:
                return size
    except ValueError:
        # Fallback return statement if the call stack is not deep enough
        return size
