# Assuming ImportInfo is defined elsewhere in the codebase
class ImportInfo:
    module: List[str]
    name: List[str]
    alias: Optional[str] = None

def get_module_info_from_python_file(path: str) -> Generator[ImportInfo, None, None]:
    with open(path, encoding='utf-8') as fh:  # Specify UTF-8 encoding
        root = ast.parse(fh.read(), path)

    for node in ast.iter_child_nodes(root):
        if isinstance(node, ast.Import):
            module = []
        elif isinstance(node, ast.ImportFrom):
            module = node.module.split('.') if node.module else []  # Check if node.module is empty
        else:
            continue

        if hasattr(node, 'names'):  # Check if node has 'names' attribute
            for n in node.names:
                yield ImportInfo(module=module, name=n.name.split('.'), alias=n.asname)  # Use ImportInfo type
