def pretty_date(time, now=None):
    """
    Get a datetime object or an int() Epoch timestamp and return a
    pretty string like 'an hour ago', 'yesterday', '3 months ago',
    'just now', etc.
    """
    from datetime import datetime

    # Check the type of the 'time' parameter
    if not isinstance(time, (int, datetime)):
        raise ValueError("Parameter 'time' must be an integer or a datetime object.")

    # Determine the 'now' reference point
    if now is None:
        now = datetime.now()

    if isinstance(time, int):
        diff = now - datetime.fromtimestamp(time)
    elif isinstance(time, datetime):
        diff = now - time

    second_diff = diff.seconds
    day_diff = diff.days

    if day_diff < 0:
        return ''

    if day_diff == 0:
        if second_diff < 10:
            return "just now"
        if second_diff < 60:
            return str(second_diff) + " seconds ago"
        if second_diff < 120:
            return "a minute ago"
        if second_diff < 3600:
            return str(second_diff // 60) + " minutes ago"
        if second_diff < 7200:
            return "an hour ago"
        if second_diff < 86400:
            return str(second_diff // 3600) + " hours ago"

    if day_diff == 1:
        return "yesterday"

    if day_diff < 7:
        return str(day_diff) + " days ago"

    weeks = day_diff // 7
    if weeks == 1:
        return "a week ago"
    if day_diff < 28:
        return str(weeks) + " weeks ago"

    months = day_diff // 30
    if months == 1:
        return "a month ago"
    if months == 12:
        months -= 1
    if day_diff < 365:
        return str(months) + " months ago"

    years = day_diff // 365
    if years == 1:
        return "a year ago"
    return str(years) + " years ago"
