def set_wallpaper(file_loc: str, first_run: bool = True) -> bool:
    """Sets the wallpaper for the current desktop environment."""
    from gi.repository import Gio
    import configparser

    desktop_env = get_desktop_environment()
    try:
        if desktop_env in ["gnome", "unity", "cinnamon"]:
            uri = Path(file_loc).as_uri()
            try:
                SCHEMA = "org.gnome.desktop.background"
                KEY = "picture-uri"
                gsettings = Gio.Settings.new(SCHEMA)
                gsettings.set_string(KEY, uri)

                # Dark mode support
                DARK_MODE_KEY = "picture-uri-dark"
                if gsettings.get_string(DARK_MODE_KEY):
                    gsettings.set_string(DARK_MODE_KEY, uri)
            except Exception:
                args = ["gsettings", "set", "org.gnome.desktop.background", "picture-uri", uri]
                subprocess.Popen(args)
        elif desktop_env == "mate":
            try:  # MATE >= 1.6
                args = ["gsettings", "set", "org.mate.background", "picture-filename", file_loc]
                subprocess.Popen(args)
            except Exception:  # MATE < 1.6
                args = ["mateconftool-2", "-t", "string", "--set", "/desktop/mate/background/picture_filename", file_loc]
                subprocess.Popen(args)
        elif desktop_env == "gnome2":  # Not tested
            args = ["gconftool-2", "-t", "string", "--set", "/desktop/gnome/background/picture_filename", file_loc]
            subprocess.Popen(args)
        elif desktop_env in ["kde3", "trinity"]:
            args = ["dcop", "kdesktop", "KBackgroundIface", "setWallpaper", "0", file_loc, "6"]
            subprocess.Popen(args)
        elif desktop_env == "xfce4":
            if first_run:
                args0 = ["xfconf-query", "-c", "xfce4-desktop", "-p", "/backdrop/screen0/monitor0/image-path", "-s", file_loc]
                args1 = ["xfconf-query", "-c", "xfce4-desktop", "-p", "/backdrop/screen0/monitor0/image-style", "-s", "3"]
                args2 = ["xfconf-query", "-c", "xfce4-desktop", "-p", "/backdrop/screen0/monitor0/image-show", "-s", "true"]
                subprocess.Popen(args0)
                subprocess.Popen(args1)
                subprocess.Popen(args2)
            args = ["xfdesktop", "--reload"]
            subprocess.Popen(args)
        elif desktop_env == "razor-qt":
            if first_run:
                desktop_conf = configparser.ConfigParser()
                desktop_conf_file = os.path.join(get_config_dir("razor"), "desktop.conf")
                if os.path.isfile(desktop_conf_file):
                    config_option = r"screens\1\desktops\1\wallpaper"
                else:
                    desktop_conf_file = os.path.join(get_home_dir(), ".razor/desktop.conf")
                    config_option = r"desktops\1\wallpaper"
                desktop_conf.read(desktop_conf_file)
                try:
                    if desktop_conf.has_option("razor", config_option):
                        desktop_conf.set("razor", config_option, file_loc)
                        with open(desktop_conf_file, "w", encoding="utf-8", errors="replace") as f:
                            desktop_conf.write(f)
                except Exception:
                    pass
        elif desktop_env in ["fluxbox", "jwm", "openbox", "afterstep"]:
            try:
                args = ["fbsetbg", file_loc]
                subprocess.Popen(args)
            except Exception:
                sys.stderr.write("ERROR: Failed to set wallpaper with fbsetbg!\n")
                sys.stderr.write("Please make sure that you have fbsetbg installed.\n")
        elif desktop_env == "icewm":
            args = ["icewmbg", file_loc]
            subprocess.Popen(args)
        elif desktop_env == "blackbox":
            args = ["bsetbg", "-full", file_loc]
            subprocess.Popen(args)
        elif desktop_env == "lxde":
            args = ["pcmanfm", "--set-wallpaper", file_loc, "--wallpaper-mode=scaled"]
            subprocess.Popen(args)
        elif desktop_env == "windowmaker":
            args = ["wmsetbg", "-s", "-u", file_loc]
            subprocess.Popen(args)
        elif desktop_env == "windows":
            SPI_SETDESKWALLPAPER = 20
            ctypes.windll.user32.SystemParametersInfoW(SPI_SETDESKWALLPAPER, 0, file_loc, 0)
        elif desktop_env == "mac":
            try:
                from appscript import app, mactypes
                app('Finder').desktop_picture.set(mactypes.File(file_loc))
            except ImportError:
                script = f"""
                /usr/bin/osascript<<END
                tell application "Finder" to
                set desktop picture to POSIX file "{file_loc}"
                end tell
                END"""
                subprocess.Popen(script, shell=True)
        else:
            if first_run:
                sys.stderr.write("Warning: Failed to set wallpaper. Your desktop environment is not supported.\n")
                sys.stderr.write(f"You can try manually to set your wallpaper to {file_loc}\n")
            return False
        return True
    except Exception:
