import urllib
from typing import Dict
import urllib.parse

def recursive_urlencode(d: Dict) -> str:
    """URL-encode a multidimensional dictionary.

    >>> data = {'a': 'b&c', 'd': {'e': {'f&g': 'h*i'}}, 'j': 'k'}
    >>> recursive_urlencode(data)
    u'a=b%26c&j=k&d[e][f%26g]=h%2Ai'
    """
    def _recursion(d, base=[]):
        pairs = []

        for key, value in d.items():
            new_base = base + [key]
            if hasattr(value, 'values'):
                pairs += _recursion(value, new_base)
            else:
                new_pair = None
                if len(new_base) > 1:
                    first = urllib.parse.quote(new_base.pop(0))
                    rest = map(lambda x: urllib.parse.quote(x), new_base)
                    new_pair = f"{first}[{']['.join(rest)}]={urllib.parse.quote(str(value))}"
                else:
                    new_pair = f"{urllib.parse.quote(str(key))}={urllib.parse.quote(str(value))}"
                pairs.append(new_pair)
        return pairs

    return '&'.join(_recursion(d))
