def _split_multipolygon_into_outer_and_inner(geom: shapely.geometry.base.BaseGeometry):
    if geom.geom_type == 'Polygon':
        exterior_coords = geom.exterior.coords[:]
        interior_coords = []
        for interior in geom.interiors:
            interior_coords += interior.coords[:]
    elif geom.geom_type == 'MultiPolygon':
        exterior_coords = []
        interior_coords = []
        for part in geom:
            epc = _split_multipolygon_into_outer_and_inner(part)  # Recursive call
            exterior_coords += epc[0]  # Accessing tuple elements
            interior_coords += epc[1]
    else:
        raise ValueError(f'Unhandled geometry type: {repr(geom.geom_type)}')
    return exterior_coords, interior_coords  # Returning a tuple
