def ingest() -> pd.DataFrame:
    import requests
    import pandas as pd
    from datetime import datetime

    apiBase = 'https://query2.finance.yahoo.com'
    headers = { 
      "User-Agent": 
      "Mozilla/5.0 (Windows NT 6.1; Win64; x64)"
    }

    def getCredentials(cookieUrl='https://fc.yahoo.com', crumbUrl=apiBase+'/v1/test/getcrumb'):
        cookie = requests.get(cookieUrl, timeout=10).cookies
        crumb = requests.get(url=crumbUrl, cookies=cookie, headers=headers, timeout=10).text
        return {'cookie': cookie, 'crumb': crumb}

    def quote(symbols, credentials):
        url = apiBase + '/v7/finance/quote'
        params = {'symbols': ','.join(symbols), 'crumb': credentials['crumb']}
        response = requests.get(url, params=params, cookies=credentials['cookie'], headers=headers)
        quotes = response.json()['quoteResponse']['result']
        return quotes

    credentials = getCredentials()
    quotes = quote(['GOOG', 'TSLA', 'AAPL', 'MSFT'], credentials)

    prices = []
    metric_names = []
    if quotes:
        for quote in quotes:
            prices.append(quote['regularMarketPrice'])
            metric_names.append(f"yf_{quote['symbol'].lower()}_price")

    metric_timestamp = datetime.now()

    df = pd.DataFrame({
        'metric_name': metric_names,
        'price': prices,
        'metric_timestamp': metric_timestamp
    })

    return df
