def generate_oriented_forest(n): 
    """SIAM J. COMPUT. Vol. 9, No. 4, November 1980
    T. Beyer and S.M. Hedetniemi: constant time generation of rooted trees.""" 

    P = list(range(-1, n)) 
    while True: 
        yield P[1:] 
        if P[n] > 0: 
            P[n] = P[P[n]] 
        else:
            for p in range(n-1, 0, -1): 
                if P[p] != 0: 
